				var checkboxSelector = "#ysnSearchOnlyDept" + 'd8d416c7-f932-4da6-807b-e6da774d3fc8';
				var buttonSelector = ".widgetSearchButton" + 'd8d416c7-f932-4da6-807b-e6da774d3fc8';
				var autoCompleteCache = {};
				var autoCompleteCacheKeys = [];
